// color palette

var colors = ['#f0101c', '#f05697', '#0b469b', '#32b6c3', '#f78000', '#fddf0e', '#9fe063', '#315423', '#16141b'];

// scale of the vector field 
// smaller values => bigger structures  
// bigger values  ==> smaller structures 

var myScale = 2;

// number of drawing agents 

var nAgents = 500;

var agent = [];

// set spinning direction (plus or minus)

var direction = 1;

var par = 0;

var border = 150;

var widthRescale;

function setup() {

	let d = displayDensity();

	let isMobile = /Mobi|Android|iPhone|iPad|iPod/i.test(navigator.userAgent);

  if (isMobile) {
		pixelDensity(1);
		createCanvas(windowWidth*0.9,windowWidth*0.9);
  } else {
		pixelDensity(d);
		createCanvas(800,800);
  }

	widthRescale = 800/width;

	border = border*widthRescale;

	frameRate(20);

	colorMode(HSB, 360, 100, 100,100);
	rectMode(CENTER);
	strokeCap(SQUARE);

	background(100);

	for (let i = 0; i < nAgents; i++) {
		agent.push(new Agent());
	}

}

function draw() {

	stroke(0);
	noFill();
	strokeWeight(10*widthRescale);
	rect(width/2,height/2,width,height);

	for (let i = 0; i < agent.length; i++) 
	{
		//if (frameCount > 50)
		{
		  agent[i].update();
		}
	}

}


// paintining agent 


class Agent {
	constructor() {
		this.p = createVector(random(border, width - border), random(border, height - border));

		this.pOld = createVector(this.p.x, this.p.y);

		this.step = 0.25*widthRescale;

		this.rad =  30/widthRescale;

		this.color = random(colors);

		if (random(0, 1) > 0.5) {
			this.direction = 1;
		} else {
			this.direction = -1;
		}

		this.myrand = random(0,1);

		this.strokeWidth = 0.5*widthRescale;

	}

	getRad() 
	{
     return this.rad;
	}

	update() {

		if (random(0, 1) < 1.0e-4) {
			this.direction *= -1;
		}

		if (frameCount > 50)
		{
		  this.p.x += direction * vector_field(this.p.x, this.p.y).x * this.step ;
		  this.p.y += direction * vector_field(this.p.x, this.p.y).y * this.step ;
		}

		strokeWeight(this.strokeWidth);
    stroke(this.color);
		fill(100);

		if (this.rad > 1)
		{
			if(this.myrand < 0.5) 
			{
		    ellipse(this.p.x, this.p.y, this.rad,this.rad);
			  this.rad -= 0.1;
			}

		}

		this.pOld.set(this.p);

	}

}

// vector field function 
// the painting agents follow the flow defined 
// by this function 


function vector_field(x, y) {

	x = map(x, 0, width,  0, myScale);
	y = map(y, 0, height, 0, myScale);


	let k1 = map(x,-myScale,myScale,-15,15);
  let k2 = map(y,-myScale,myScale,-15,15);

	let u = sin(k1 * y) + cos(k2 * y);
	let v = sin(k2 * x) - cos(k1 * x);

	return createVector(u, v);
}
